        deviceStats: _logsJsonTrimStats(_logsJsonTable(data, "deviceStats")),
        appStats: _logsJsonTrimStats(_logsJsonTable(data, "appStats")),
        jobs: _logsJsonTable(data, "jobs").collect { job ->
