private Map _fetchAppsListTree(String caller) {
    def responseText
    try {
        responseText = hubInternalGet("/hub2/appsList")
    } catch (Exception e) {
        throw new IllegalArgumentException("Failed to fetch installed apps for ${caller} [${e.class.simpleName}]: ${e.message ?: e.toString()}")
    }
    if (!responseText) {
        throw new IllegalArgumentException("Empty response from /hub2/appsList during ${caller} -- hub internal API may be unavailable")
    }
    try {
        return new groovy.json.JsonSlurper().parseText(responseText)
    } catch (Exception e) {
        throw new IllegalArgumentException("Failed to parse /hub2/appsList for ${caller}: ${e.message ?: e.toString()}")
    }
}
private String _hpmDiscoverAppId() {
    def parsed = _fetchAppsListTree("HPM discovery")
    def hpmMatches = []
    def workQueue = [] + (parsed?.apps ?: [])
    int qi = 0
    while (qi < workQueue.size()) {
        def node = workQueue[qi++]
        def d = node?.data ?: [:]
        if (d.type?.toString() == "Hubitat Package Manager") {
            if (d.id == null) throw new IllegalArgumentException("HPM entry found but has no id field -- cannot determine hpmAppId; pass hpmAppId explicitly")
            hpmMatches << d.id.toString()
        }
        (node?.children ?: []).each { workQueue << it }
    }
    if (hpmMatches.isEmpty()) {
        throw new IllegalArgumentException("HPM not found in installed apps -- Hubitat Package Manager does not appear to be installed")
    }
    if (hpmMatches.size() > 1) {
        def cap = 10
        def shown = hpmMatches.take(cap).join(', ')
        def extra = hpmMatches.size() > cap ? " and ${hpmMatches.size() - cap} more (total ${hpmMatches.size()})" : ""
        throw new IllegalArgumentException("Multiple HPM instances found: [${shown}]${extra} -- pass hpmAppId explicitly to select one")
    }
    return hpmMatches[0]
}
private void _hpmAssertAppIsHpm(String explicitAppId) {
    def parsed = _fetchAppsListTree("hpmAppId validation")
    def workQueue = [] + (parsed?.apps ?: [])
    int qi = 0
    def foundEntry = null
    while (qi < workQueue.size() && foundEntry == null) {
        def node = workQueue[qi++]
        def d = node?.data ?: [:]
        if (d.id?.toString() == explicitAppId) {
            foundEntry = d
        } else {
            (node?.children ?: []).each { workQueue << it }
        }
    }
    if (foundEntry == null) {
        throw new IllegalArgumentException("hpmAppId ${explicitAppId} not found in installed apps -- verify the ID or omit hpmAppId to use auto-discovery")
    }
    def actualType = foundEntry.type?.toString() ?: "unknown"
    if (actualType != "Hubitat Package Manager") {
        throw new IllegalArgumentException("hpmAppId ${explicitAppId} is not Hubitat Package Manager (actual type: ${actualType}) -- verify the ID or omit hpmAppId to use auto-discovery")
    }
}
private Map _hpmFetchManifests(String hpmAppId) {
    def responseText
    try {
        responseText = hubInternalGet("/installedapp/statusJson/${hpmAppId}")
    } catch (Exception e) {
        throw new IllegalArgumentException("Failed to fetch HPM statusJson [${e.class.simpleName}]: ${e.message ?: e.toString()}")
    }
    if (!responseText) {
        throw new IllegalArgumentException("Empty response from /installedapp/statusJson/${hpmAppId} -- app may not exist or hub internal API is unavailable")
    }
    def outer
    try {
        outer = new groovy.json.JsonSlurper().parseText(responseText)
    } catch (Exception e) {
        throw new IllegalArgumentException("Failed to parse HPM statusJson [${e.class.simpleName}]: ${e.message ?: e.toString()}")
    }
    if (!(outer instanceof Map)) {
        def actualTypeName = (outer instanceof List) ? "List" : (outer == null ? "null" : "non-object")
        throw new IllegalArgumentException("Unexpected HPM statusJson shape: expected a JSON object, got ${actualTypeName}")
    }
    def appState = outer.appState ?: []
    def manifestsEntry = appState.find { it?.name?.toString() == "manifests" }
    if (manifestsEntry == null) {
        return [:]
    }
    def rawValue = manifestsEntry.value
    if (rawValue == null) {
        return [:]
    }
    def manifests
    if (rawValue instanceof Map) {
        manifests = rawValue
    } else {
        def rawStr = rawValue.toString().trim()
        if (rawStr.isEmpty()) return [:]
        try {
            manifests = new groovy.json.JsonSlurper().parseText(rawStr)
        } catch (Exception e) {
            throw new IllegalArgumentException("Failed to parse HPM manifests value [${e.class.simpleName}]: ${e.message ?: e.toString()}")
        }
    }
    if (!(manifests instanceof Map)) {
        def actualTypeName = (manifests instanceof List) ? "List" : (manifests == null ? "null" : "non-object")
        throw new IllegalArgumentException("Unexpected HPM manifests shape: expected a JSON object keyed by manifest URL, got ${actualTypeName}")
    }
    return manifests
}
def toolListHpmPackages(args) {
    def hpmAppId
    if (args?.hpmAppId != null && args.hpmAppId.toString().trim() != "") {
        hpmAppId = args.hpmAppId.toString().trim()
        if (!hpmAppId.isInteger()) {
            throw new IllegalArgumentException("hpmAppId must be numeric: ${hpmAppId}")
        }
        _hpmAssertAppIsHpm(hpmAppId)
    } else {
        hpmAppId = _hpmDiscoverAppId()
    }
    mcpLog("info", "hpm", "hub_list_hpm_packages hpmAppId=${hpmAppId}")
    def manifests
    try {
        manifests = _hpmFetchManifests(hpmAppId)
    } catch (IllegalArgumentException e) {
        return [success: false, error: e.message, hpmAppId: hpmAppId]
    }
    def skippedMalformed = []
    def packages = manifests.collect { manifestUrl, manifest ->
        if (!(manifest instanceof Map)) {
            mcpLog("warn", "hpm", "hub_list_hpm_packages: skipping malformed manifest entry for URL ${manifestUrl} -- value is not a Map")
            skippedMalformed << manifestUrl?.toString()
            return null
        }
        int skippedAppCount = 0
        int skippedDriverCount = 0
        int skippedFileCount = 0
        def apps = (manifest.apps ?: []).collect { a ->
            if (!(a instanceof Map)) { skippedAppCount++; mcpLog("warn", "hpm", "hub_list_hpm_packages: non-Map app component in '${manifest.packageName}' (value: ${a?.toString()?.take(60) ?: 'null'}) -- skipped"); return null }
            def heId = a.heID
            def heIdStr = null
            def heIdWarning = null
            if (heId instanceof String && heId.trim() == "") {
                heIdWarning = "empty heID string '${heId}' normalized to null"
                heId = null
                mcpLog("warn", "hpm", "hub_list_hpm_packages: app '${a.name}' in '${manifest.packageName}' heID is empty/whitespace -- normalized to null")
            }
            if (heId instanceof String && heId.trim() != heId) {
                def trimmed = heId.trim()
                heIdWarning = "whitespace-padded heID '${heId}' normalized to '${trimmed}'"
                mcpLog("warn", "hpm", "hub_list_hpm_packages: app '${a.name}' in '${manifest.packageName}' heID has surrounding whitespace -- normalized to '${trimmed}'")
                heId = trimmed
            }
            if (heId != null) {
                if (heId instanceof Number || heId instanceof String) {
                    heIdStr = heId.toString()
                } else {
                    heIdWarning = "non-scalar heID (not Number or String) -- heID cleared"
                    mcpLog("warn", "hpm", "hub_list_hpm_packages: app '${a.name}' in '${manifest.packageName}' heID is not a Number or String -- skipping heID")
                }
            }
            def entry = [
                id      : a.id?.toString(),
                name    : a.name?.toString(),
                required: a.required == true,
                version : a.version?.toString(),
                heID    : heIdStr
            ]
            if (heIdWarning) entry._warning = heIdWarning
            entry
        }.findAll { it != null }
        def drivers = (manifest.drivers ?: []).collect { d ->
            if (!(d instanceof Map)) { skippedDriverCount++; mcpLog("warn", "hpm", "hub_list_hpm_packages: non-Map driver component in '${manifest.packageName}' (value: ${d?.toString()?.take(60) ?: 'null'}) -- skipped"); return null }
            def heId = d.heID
            def heIdStr = null
            def heIdWarning = null
            if (heId instanceof String && heId.trim() == "") {
                heIdWarning = "empty heID string '${heId}' normalized to null"
                heId = null
                mcpLog("warn", "hpm", "hub_list_hpm_packages: driver '${d.name}' in '${manifest.packageName}' heID is empty/whitespace -- normalized to null")
            }
            if (heId instanceof String && heId.trim() != heId) {
                def trimmed = heId.trim()
                heIdWarning = "whitespace-padded heID '${heId}' normalized to '${trimmed}'"
                mcpLog("warn", "hpm", "hub_list_hpm_packages: driver '${d.name}' in '${manifest.packageName}' heID has surrounding whitespace -- normalized to '${trimmed}'")
                heId = trimmed
            }
            if (heId != null) {
                if (heId instanceof Number || heId instanceof String) {
                    heIdStr = heId.toString()
                } else {
                    heIdWarning = "non-scalar heID (not Number or String) -- heID cleared"
                    mcpLog("warn", "hpm", "hub_list_hpm_packages: driver '${d.name}' in '${manifest.packageName}' heID is not a Number or String -- skipping heID")
                }
            }
            def entry = [
                id      : d.id?.toString(),
                name    : d.name?.toString(),
                required: d.required == true,
                version : d.version?.toString(),
                heID    : heIdStr
            ]
            if (heIdWarning) entry._warning = heIdWarning
            entry
        }.findAll { it != null }
        def files = (manifest.files ?: []).collect { f ->
            if (!(f instanceof Map)) { skippedFileCount++; mcpLog("warn", "hpm", "hub_list_hpm_packages: non-Map file component in '${manifest.packageName}' (value: ${f?.toString()?.take(60) ?: 'null'}) -- skipped"); return null }
            [
                id  : f.id?.toString(),
                name: f.name?.toString()
            ]
        }.findAll { it != null }
        def pkg = [
            manifestUrl : manifestUrl?.toString(),
            packageName : manifest.packageName?.toString(),
            version     : manifest.version?.toString(),
            beta        : manifest.beta == true,
            author      : manifest.author?.toString(),
            apps        : apps,
            drivers     : drivers,
            files       : files
        ]
        if (skippedAppCount > 0)    pkg.skippedAppCount    = skippedAppCount
        if (skippedDriverCount > 0) pkg.skippedDriverCount = skippedDriverCount
        if (skippedFileCount > 0)   pkg.skippedFileCount   = skippedFileCount
        pkg
    }.findAll { it != null }
    def cursor = args?.cursor
    def paged = _paginateList(packages, cursor, 25, "hub_list_hpm_packages")
    def result = [
        success   : true,
        hpmAppId  : hpmAppId,
        count     : paged.page.size(),
        packages  : paged.page
    ]
    if (cursor != null) {
        result.total = packages.size()
        if (paged.nextCursor != null) result.nextCursor = paged.nextCursor
    }
    if (skippedMalformed) result.skippedMalformed = skippedMalformed
    return result
}
def toolGetHpmDrift(args) {
    def hpmAppId
    if (args?.hpmAppId != null && args.hpmAppId.toString().trim() != "") {
        hpmAppId = args.hpmAppId.toString().trim()
        if (!hpmAppId.isInteger()) {
            throw new IllegalArgumentException("hpmAppId must be numeric: ${hpmAppId}")
        }
        _hpmAssertAppIsHpm(hpmAppId)
    } else {
        hpmAppId = _hpmDiscoverAppId()
    }
    def packageFilterRaw = args?.packageFilter?.toString()?.trim()
    def packageFilter = packageFilterRaw ?: null
    mcpLog("info", "hpm", "get_hpm_drift hpmAppId=${hpmAppId} packageFilter=${packageFilter ?: 'none'}")
    def manifests
    try {
        manifests = _hpmFetchManifests(hpmAppId)
    } catch (IllegalArgumentException e) {
        return [success: false, error: e.message, hpmAppId: hpmAppId]
    }
    def installedAppCodeIds = [] as Set
    def orphanDetection = [enabled: true]
    try {
        def userAppTypesText = hubInternalGet("/hub2/userAppTypes")
        if (!userAppTypesText) {
            orphanDetection = [enabled: false, reason: "Empty response from /hub2/userAppTypes -- orphan-app signals were not evaluated this call"]
            mcpLog("warn", "hpm", "get_hpm_drift: empty /hub2/userAppTypes response -- orphan detection disabled")
        } else {
            def userAppTypesParsed = new groovy.json.JsonSlurper().parseText(userAppTypesText)
            if (!(userAppTypesParsed instanceof List)) {
                def actualTypeName = _typeName(userAppTypesParsed)
                def rawPreview = userAppTypesParsed?.toString() ?: ""
                def actualPreview = rawPreview.length() > 200 ? rawPreview.take(200) + " (truncated)" : rawPreview
                orphanDetection = [enabled: false, reason: "Unexpected /hub2/userAppTypes response shape (expected JSON array, got ${actualTypeName}: ${actualPreview}) -- orphan-app signals were not evaluated this call"]
                mcpLog("warn", "hpm", "get_hpm_drift: /hub2/userAppTypes returned non-List shape (${actualTypeName}) -- orphan detection disabled")
            } else {
                userAppTypesParsed.each { t ->
                    def typeId = t?.id?.toString()
                    if (typeId) installedAppCodeIds << typeId
                }
            }
        }
    } catch (Exception e) {
        orphanDetection = [enabled: false, reason: "Failed to fetch /hub2/userAppTypes [${e.class.simpleName}]: ${e.message ?: e.toString()} -- orphan-app signals were not evaluated this call"]
        mcpLog("warn", "hpm", "get_hpm_drift: could not fetch /hub2/userAppTypes for orphan-app detection: ${e.message ?: e.toString()}")
    }
    def installedDriverCodeIds = [] as Set
    def orphanDriverDetection = [enabled: true]
    try {
        def userDeviceTypesText = hubInternalGet("/hub2/userDeviceTypes")
        if (!userDeviceTypesText) {
            orphanDriverDetection = [enabled: false, reason: "Empty response from /hub2/userDeviceTypes -- orphan-driver signals were not evaluated this call"]
            mcpLog("warn", "hpm", "get_hpm_drift: empty /hub2/userDeviceTypes response -- orphan driver detection disabled")
        } else {
            def userDeviceTypesParsed = new groovy.json.JsonSlurper().parseText(userDeviceTypesText)
            if (!(userDeviceTypesParsed instanceof List)) {
                def actualTypeName = _typeName(userDeviceTypesParsed)
                def rawPreview = userDeviceTypesParsed?.toString() ?: ""
                def actualPreview = rawPreview.length() > 200 ? rawPreview.take(200) + " (truncated)" : rawPreview
                orphanDriverDetection = [enabled: false, reason: "Unexpected /hub2/userDeviceTypes response shape (expected JSON array, got ${actualTypeName}: ${actualPreview}) -- orphan-driver signals were not evaluated this call"]
                mcpLog("warn", "hpm", "get_hpm_drift: /hub2/userDeviceTypes returned non-List shape (${actualTypeName}) -- orphan driver detection disabled")
            } else {
                userDeviceTypesParsed.each { t ->
                    def typeId = t?.id?.toString()
                    if (typeId) installedDriverCodeIds << typeId
                }
            }
        }
    } catch (Exception e) {
        orphanDriverDetection = [enabled: false, reason: "Failed to fetch /hub2/userDeviceTypes [${e.class.simpleName}]: ${e.message ?: e.toString()} -- orphan-driver signals were not evaluated this call"]
        mcpLog("warn", "hpm", "get_hpm_drift: could not fetch /hub2/userDeviceTypes for orphan-driver detection: ${e.message ?: e.toString()}")
    }
    def filteredManifests = packageFilter
        ? manifests.findAll { url, m -> m instanceof Map && m.packageName?.toString()?.toLowerCase()?.contains(packageFilter.toLowerCase()) }
        : manifests
    def driftEntries = []
    def driftSkippedMalformed = []
    def driftDataQualityWarnings = []
    int totalSignals = 0
    filteredManifests.each { manifestUrl, manifest ->
        if (!(manifest instanceof Map)) {
            mcpLog("warn", "hpm", "get_hpm_drift: skipping malformed manifest entry for URL ${manifestUrl} -- value is not a Map")
            driftSkippedMalformed << manifestUrl?.toString()
            return
        }
        def signals = []
        def dataQualityWarnings = []
        int skippedAppCount = 0
        int skippedDriverCount = 0
        (manifest.apps ?: []).each { a ->
            if (!(a instanceof Map)) {
                skippedAppCount++
                dataQualityWarnings << [
                    type         : "skipped-malformed-component",
                    componentType: "app",
                    _warning     : "app component entry is not a Map -- skipped"
                ]
                mcpLog("warn", "hpm", "get_hpm_drift: non-Map app component in '${manifest.packageName}' (value: ${a?.toString()?.take(60) ?: 'null'}) -- skipped")
                return
            }
            def heId = a.heID
            if (heId instanceof String && heId.trim() == "") {
                dataQualityWarnings << [
                    type         : "empty-heid",
                    componentType: "app",
                    componentName: a.name?.toString(),
                    componentId  : a.id?.toString(),
                    _warning     : "empty heID string '${heId}' normalized to null"
                ]
                mcpLog("warn", "hpm", "get_hpm_drift: app '${a.name}' in '${manifest.packageName}' heID is empty/whitespace -- normalized to null")
                heId = null
            }
            if (heId instanceof String && heId.trim() != heId) {
                def trimmed = heId.trim()
                dataQualityWarnings << [
                    type         : "heid-whitespace-normalized",
                    componentType: "app",
                    componentName: a.name?.toString(),
                    componentId  : a.id?.toString(),
                    _warning     : "whitespace-padded heID '${heId}' normalized to '${trimmed}'"
                ]
                mcpLog("warn", "hpm", "get_hpm_drift: app '${a.name}' in '${manifest.packageName}' heID has surrounding whitespace ('${heId}') -- normalized to '${trimmed}'")
                heId = trimmed
            }
            if (heId != null && !(heId instanceof Number) && !(heId instanceof String)) {
                mcpLog("warn", "hpm", "get_hpm_drift: app '${a.name}' in '${manifest.packageName}' heID is not a Number or String (value: ${heId?.toString()?.take(60) ?: 'null'}) -- skipping component")
                dataQualityWarnings << [
                    type         : "heid-non-scalar-dropped",
                    componentType: "app",
                    componentName: a.name?.toString(),
                    componentId  : a.id?.toString(),
                    _warning     : "non-scalar heID (not Number or String) -- component skipped"
                ]
                return
            }
            def heIdNull = heId == null
            if (a.required == true && heIdNull) {
                signals << [
                    type         : "missing-required",
                    componentType: "app",
                    componentName: a.name?.toString(),
                    componentId  : a.id?.toString(),
                    note         : "Component is required but heID is null/absent -- install never completed or component was removed."
                ]
            }
            if (!heIdNull && orphanDetection.enabled) {
                def heIdStr = heId.toString()
                if (!installedAppCodeIds.contains(heIdStr)) {
                    signals << [
                        type         : "orphan-app",
                        componentType: "app",
                        componentName: a.name?.toString(),
                        componentId  : a.id?.toString(),
                        heID         : heIdStr,
                        note         : "HPM tracks heID ${heIdStr} but the app code definition is no longer in Apps Code -- likely deleted via Apps Code without using HPM Uninstall."
                    ]
                }
            }
        }
        (manifest.drivers ?: []).each { d ->
            if (!(d instanceof Map)) {
                skippedDriverCount++
                dataQualityWarnings << [
                    type         : "skipped-malformed-component",
                    componentType: "driver",
                    _warning     : "driver component entry is not a Map -- skipped"
                ]
                mcpLog("warn", "hpm", "get_hpm_drift: non-Map driver component in '${manifest.packageName}' (value: ${d?.toString()?.take(60) ?: 'null'}) -- skipped")
                return
            }
            def heId = d.heID
            if (heId instanceof String && heId.trim() == "") {
                dataQualityWarnings << [
                    type         : "empty-heid",
                    componentType: "driver",
                    componentName: d.name?.toString(),
                    componentId  : d.id?.toString(),
                    _warning     : "empty heID string '${heId}' normalized to null"
                ]
                mcpLog("warn", "hpm", "get_hpm_drift: driver '${d.name}' in '${manifest.packageName}' heID is empty/whitespace -- normalized to null")
                heId = null
            }
            if (heId instanceof String && heId.trim() != heId) {
                def trimmed = heId.trim()
                dataQualityWarnings << [
                    type         : "heid-whitespace-normalized",
                    componentType: "driver",
                    componentName: d.name?.toString(),
                    componentId  : d.id?.toString(),
                    _warning     : "whitespace-padded heID '${heId}' normalized to '${trimmed}'"
                ]
                mcpLog("warn", "hpm", "get_hpm_drift: driver '${d.name}' in '${manifest.packageName}' heID has surrounding whitespace ('${heId}') -- normalized to '${trimmed}'")
                heId = trimmed
            }
            if (heId != null && !(heId instanceof Number) && !(heId instanceof String)) {
                mcpLog("warn", "hpm", "get_hpm_drift: driver '${d.name}' in '${manifest.packageName}' heID is not a Number or String (value: ${heId?.toString()?.take(60) ?: 'null'}) -- skipping component")
                dataQualityWarnings << [
                    type         : "heid-non-scalar-dropped",
                    componentType: "driver",
                    componentName: d.name?.toString(),
                    componentId  : d.id?.toString(),
                    _warning     : "non-scalar heID (not Number or String) -- component skipped"
                ]
                return
            }
            def heIdNull = heId == null
            if (d.required == true && heIdNull) {
                signals << [
                    type         : "missing-required",
                    componentType: "driver",
                    componentName: d.name?.toString(),
                    componentId  : d.id?.toString(),
                    note         : "Component is required but heID is null/absent -- install never completed or component was removed."
                ]
            }
            if (!heIdNull && orphanDriverDetection.enabled) {
                def heIdStr = heId.toString()
                if (!installedDriverCodeIds.contains(heIdStr)) {
                    signals << [
                        type         : "orphan-driver",
                        componentType: "driver",
                        componentName: d.name?.toString(),
                        componentId  : d.id?.toString(),
                        heID         : heIdStr,
                        note         : "HPM tracks heID ${heIdStr} but the driver code definition is no longer in Drivers Code -- likely deleted via Drivers Code without using HPM Uninstall."
                    ]
                }
            }
        }
        if (signals || dataQualityWarnings) {
            def entry = [
                manifestUrl : manifestUrl?.toString(),
                packageName : manifest.packageName?.toString(),
                version     : manifest.version?.toString(),
                signals     : signals
            ]
            if (dataQualityWarnings) entry.dataQualityWarnings = dataQualityWarnings
            if (skippedAppCount > 0)    entry.skippedAppCount    = skippedAppCount
            if (skippedDriverCount > 0) entry.skippedDriverCount = skippedDriverCount
            driftEntries << entry
            totalSignals += signals.size()
            if (dataQualityWarnings) driftDataQualityWarnings.addAll(dataQualityWarnings)
        }
    }
    int checked = filteredManifests.size()
    int packagesWithActionableDrift = driftEntries.count { it.signals }
    def summary = packagesWithActionableDrift == 0
        ? "No drift detected across ${checked} tracked package${checked == 1 ? '' : 's'}."
        : "${packagesWithActionableDrift} of ${checked} tracked package${checked == 1 ? '' : 's'} ${packagesWithActionableDrift == 1 ? 'shows' : 'show'} drift (${totalSignals} total signal${totalSignals == 1 ? '' : 's'})."
    def partialSuffixParts = []
    if (!orphanDetection.enabled)       partialSuffixParts << "orphanDetection"
    if (!orphanDriverDetection.enabled) partialSuffixParts << "orphanDriverDetection"
    if (partialSuffixParts) {
        def reasonNoun = partialSuffixParts.size() == 1 ? 'reason' : 'reasons'
        summary += " (partial: ${partialSuffixParts.join('/')} disabled this call -- see ${partialSuffixParts.join('/')} ${reasonNoun})"
    }
    def result = [
        success                     : true,
        hpmAppId                    : hpmAppId,
        packagesChecked             : checked,
        packagesWithActionableDrift : packagesWithActionableDrift,
        drift                       : driftEntries,
        totalDriftSignals           : totalSignals,
        summary                     : summary,
        orphanDetection             : orphanDetection,
        orphanDriverDetection       : orphanDriverDetection,
        limitations                 : "Drift detection is heID-presence-only. Per-component source drift (e.g., post-hub_update_app edits) is NOT detected -- HPM stores no source hashes."
    ]
    if (driftSkippedMalformed) result.skippedMalformed = driftSkippedMalformed
    if (driftDataQualityWarnings) result.dataQualityWarnings = driftDataQualityWarnings
    if (packageFilter && checked == 0) {
        result.filterMatchedZero = true
        result.availablePackages = manifests.findAll { url, m -> m instanceof Map }
            .collect { url, m -> m.packageName?.toString() }
            .findAll { it }
    }
    return result
}
def toolListHpmPackagesWithDrift(args) {
    def listResult = toolListHpmPackages(args)
    if (args.includeDrift == true && listResult instanceof Map) {
        listResult = listResult + [drift: toolGetHpmDrift(args)]
    }
    return listResult
}
def _getAllToolDefinitions_partHpm() {
    return [
        [
            name: "hub_list_hpm_packages",
            description: """List all packages tracked by Hubitat Package Manager (HPM): name, version, beta flag, author, and component inventory (apps/drivers/files) as HPM recorded at install/update time. Requires Read master; HPM must be installed.[[FLAT_TRIM]]
Set includeDrift=true to ALSO cross-reference tracked state against what is actually installed and attach a `drift` block (missing-required / orphan signals). See `hub_get_tool_guide(section='builtin_app_tools_apps')` for the full drift-signal taxonomy, response-field reference, and caveats.[[/FLAT_TRIM]]""",
            inputSchema: [
                type: "object",
                properties: [
                    hpmAppId: [type: "string", description: "HPM's installed-app ID (decimal). Auto-discovered if omitted.[[FLAT_TRIM]] Scans installed apps for type='Hubitat Package Manager'; pass explicitly to skip that discovery call.[[/FLAT_TRIM]]"],
                    includeDrift: [type: "boolean", description: "Also attach a drift cross-reference under a `drift` key.[[FLAT_TRIM]] Signal types: missing-required/orphan-app/orphan-driver.[[/FLAT_TRIM]] Default false; adds 1-2 hub calls.", default: false],
                    packageFilter: [type: "string", description: "Drift mode only (includeDrift=true): case-insensitive substring filter on packageName."],
                    cursor: [type: "string", description: "Opt-in pagination cursor for the packages list. Omit for unbounded; pass \"\" for the first page, iterate nextCursor.[[FLAT_TRIM]] Page size 25 -- HPM entries carry full app/driver/file inventories so each entry can be large.[[/FLAT_TRIM]]"]
                ]
            ]
        ],
    ]
}
def _readOnlyToolNames_partHpm() {
    return [
        "hub_list_hpm_packages"
    ]
}
def _toolDisplayMeta_partHpm() {
    return [
        hub_list_hpm_packages: [title: "List HPM Packages", summary: "List packages tracked by Hubitat Package Manager, optionally with drift detection."]
    ]
}
def toolUpdateMcpSettings(args) {
    if (!settings.enableDeveloperMode) {
        throw new IllegalArgumentException("Developer Mode tools are disabled. Enable 'Developer Mode Tools' in MCP rule app settings to use hub_update_mcp_settings.")
    }
    requireDestructiveConfirm(args.confirm)
    if (!args.settings || !(args.settings instanceof Map) || args.settings.isEmpty()) {
        throw new IllegalArgumentException("settings must be a non-empty map of {settingName: newValue}")
    }
    def allowedSettings = [
        "mcpLogLevel":            "enum",
        "debugLogging":           "bool",
        "maxCapturedStates":      "number",
        "loopGuardMax":           "number",
        "loopGuardWindowSec":     "number",
        "enableRead":             "bool",
        "enableCustomRuleEngine": "bool",
        "useGateways":            "bool",
        "enableMandatoryBPS":     "bool",
        "bypassDeviceAllowlist":  "bool",
        "maxConcurrentWrites":    "number",
        "backupEveryRuleWrite":   "bool",
        "enableLocalAccess":      "bool",
        "enableCloudAccess":      "bool",
        "redactAccessTokens":     "bool"
    ]
    def allowedKeyNames = ((allowedSettings.keySet() + ["selectedDevices"]) as List).sort()
    def updates = [:]
    boolean hasDeviceScope = false
    def deviceScopeRaw = null
    args.settings.each { key, value ->
        def keyStr = key.toString()
        if (keyStr == "selectedDevices") {
            hasDeviceScope = true
            deviceScopeRaw = value
            return
        }
        if (!allowedSettings.containsKey(keyStr)) {
            throw new IllegalArgumentException("Setting '${keyStr}' is not allowed for self-modification via hub_update_mcp_settings. Allowed: ${allowedKeyNames.join(', ')}")
        }
        def coerced = coerceSettingValue(keyStr, value, allowedSettings.get(keyStr))
        if (keyStr == "mcpLogLevel" && !getLogLevels().contains(coerced)) {
            throw new IllegalArgumentException("Setting 'mcpLogLevel' must be one of ${getLogLevels()}, got: ${coerced}")
        }
        if (keyStr == "maxConcurrentWrites") {
            BigDecimal numeric = coerced as BigDecimal
            if (numeric < 0 || numeric > 100 || numeric.remainder(BigDecimal.ONE) != BigDecimal.ZERO) {
                throw new IllegalArgumentException("Setting 'maxConcurrentWrites' must be an integer between 0 and 100 (0 disables the cap), got: ${coerced}")
            }
            coerced = numeric.intValue()
        }
        String ownTransportKey = _isCloudRequest() ? "enableCloudAccess" : "enableLocalAccess"
        if (keyStr == ownTransportKey && coerced == false) {
            throw new IllegalArgumentException("Refusing to set '${keyStr}' to false over the connection it controls: this request arrived through it, so the change would lock this client out. Turn it off from the other connection or the MCP Rule Server app page on the hub.")
        }
        updates.put(keyStr, coerced)
    }
    def deviceScopeResult = null
    if (hasDeviceScope) {
        deviceScopeResult = _validateMcpDeviceScope(deviceScopeRaw)
        if (deviceScopeResult?.success != true) {
            return deviceScopeResult
        }
    }
    mcpLog("warn", "developer-mode", "hub_update_mcp_settings: attempted=${updates}")
    if (hasDeviceScope) {
        mcpLog("warn", "developer-mode", "hub_update_mcp_settings selectedDevices: attempted mode=${deviceScopeResult.mode} resulting=${deviceScopeResult.resultIds} added=${deviceScopeResult.added} removed=${deviceScopeResult.removed}")
        app.updateSetting("selectedDevices", [type: "capability.*", value: deviceScopeResult.resultIds])
    }
    updates.each { key, value ->
        if (key == "mcpLogLevel") {
            toolSetLogLevel([level: value.toString()])
        } else {
            app.updateSetting(key, [type: allowedSettings.get(key), value: value])
        }
    }
    mcpLog("warn", "developer-mode", "hub_update_mcp_settings: applied=${updates}")
    if (hasDeviceScope) {
        mcpLog("warn", "developer-mode", "hub_update_mcp_settings selectedDevices: applied mode=${deviceScopeResult.mode} authorizedCount=${deviceScopeResult.resultIds.size()}")
    }
    def updateCount = updates.size() + (hasDeviceScope ? 1 : 0)
    def settingWord = updateCount == 1 ? "setting" : "settings"
    def schemaAffectingKeys = ["enableRead", "enableCustomRuleEngine", "useGateways"] as Set
    def touchedSchemaKey = updates.keySet().any { schemaAffectingKeys.contains(it) }
    def message = "Updated ${updateCount} ${settingWord}."
    if (touchedSchemaKey) {
        message += " MCP clients (Claude Code, etc.) may need to reconnect to refresh cached tool schemas if you toggled an enable* flag or useGateways."
    }
    def result = [
        success: true,
        updated: updates,
        message: message
    ]
    if (hasDeviceScope) {
        result.selectedDevices = [
            mode: deviceScopeResult.mode,
            authorizedDeviceIds: deviceScopeResult.authorizedDeviceIds,
            authorizedCount: deviceScopeResult.authorizedCount,
            added: deviceScopeResult.added,
            removed: deviceScopeResult.removed
        ]
        result.message = result.message + " " + deviceScopeResult.message
    }
    return result
}
private Map _validateMcpDeviceScope(scopeValue) {
    def mode = "replace"
    def rawIds
    def allowEmpty = false
    if (scopeValue instanceof List) {
        rawIds = scopeValue
    } else if (scopeValue instanceof Map) {
        mode = (scopeValue.mode == null) ? "replace" : scopeValue.mode.toString().trim()
        rawIds = scopeValue.ids
        allowEmpty = (scopeValue.allowEmpty == true)
    } else {
        throw new IllegalArgumentException("selectedDevices must be an array of device ID strings, or an object {mode, ids, allowEmpty}")
    }
    if (!(mode in ["replace", "add", "remove"])) {
        throw new IllegalArgumentException("selectedDevices mode must be one of: replace, add, remove (got: '${mode}')")
    }
    if (rawIds == null || !(rawIds instanceof List)) {
        throw new IllegalArgumentException("selectedDevices ids is required and must be an array of device ID strings")
    }
    def requestedIds = []
    rawIds.each { raw ->
        if (raw == null || raw instanceof Map || raw instanceof List) {
            throw new IllegalArgumentException("selectedDevices ids entries must be device ID strings or integers, got: ${raw}")
        }
        def s = raw.toString().trim()
        if (!s) {
            throw new IllegalArgumentException("selectedDevices ids entries must be non-empty device IDs")
        }
        if (!requestedIds.contains(s)) requestedIds << s
    }
    def currentIds = (settings.selectedDevices ?: []).collect { dev ->
        def id = (dev instanceof String || dev instanceof Number) ? dev.toString() : dev?.id?.toString()
        if (id == null) {
            throw new IllegalArgumentException("settings.selectedDevices contains an unrecognized element (neither a device with an id nor a String/Number id): ${dev}. Nothing was changed.")
        }
        id
    } as List
    def currentSet = currentIds as Set
    if (mode in ["replace", "add"] && !requestedIds.isEmpty()) {
        def inventory = _fetchAllHubDeviceRecords("developer-mode", "hub_update_mcp_settings selectedDevices")
        if (inventory.failure == "fetch") {
            return [success: false, isError: true, error: "Failed to fetch the all-hub device list (${inventory.source}) to validate selectedDevices: ${inventory.fetchError}", note: "Endpoint may be unavailable on this firmware; nothing was changed."]
        }
        if (inventory.failure) {
            return [success: false, isError: true, error: "Unexpected ${inventory.source} response; cannot validate selectedDevices.", note: "Hub firmware may have changed the endpoint contract; nothing was changed."]
        }
        def hubDeviceIds = (inventory.records.findAll { it instanceof Map }.collect { it.id?.toString() }.findAll { it != null }) as Set
        def unknown = requestedIds.findAll { !hubDeviceIds.contains(it) }
        if (inventory.idsComplete == false && mode == "add") {
            unknown = unknown.findAll { !currentSet.contains(it) }
        }
        if (!unknown.isEmpty()) {
            if (inventory.idsComplete == false) {
                return [success: false, isError: true,
                        error: "Could not validate device id(s) ${unknown.join(', ')}: the all-hub device inventory is incomplete, so they may be real devices it omitted. ${inventory.partialNote ?: ''}".toString().trim(),
                        note: "Nothing was changed. Retry once /hub2/devicesList answers; hub_list_devices(scope='all') reports the same inventory and its capabilitiesNote says what is missing."]
            }
            throw new IllegalArgumentException("Unknown device id(s): ${unknown.join(', ')}. Use hub_list_devices(scope='all') to see valid ids. Nothing was changed.")
        }
    }
    def resultIds
    switch (mode) {
        case "replace": resultIds = new ArrayList(requestedIds); break
        case "add":     def u = new LinkedHashSet(currentIds); u.addAll(requestedIds); resultIds = new ArrayList(u); break
        case "remove":  resultIds = currentIds.findAll { !requestedIds.contains(it) }; break
    }
    def resultSet = resultIds as Set
    if (resultSet.isEmpty() && !allowEmpty) {
        throw new IllegalArgumentException("Refusing to empty the MCP device-access scope: the resulting set is empty, which blinds the MCP server to every selected device. Pass selectedDevices.allowEmpty:true to confirm you intend to clear the scope.")
    }
    def added = (resultSet - currentSet) as List
    def removed = (currentSet - resultSet) as List
    def dw = { n -> n == 1 ? "device" : "devices" }
    return [
        success: true,
        mode: mode,
        resultIds: resultIds,
        authorizedDeviceIds: resultIds,
        authorizedCount: resultIds.size(),
        added: added,
        removed: removed,
        message: "MCP device-access scope updated (mode=${mode}): ${resultIds.size()} ${dw(resultIds.size())} authorized, ${added.size()} ${dw(added.size())} added, ${removed.size()} ${dw(removed.size())} removed. Device visibility changed -- MCP clients may need to reconnect to refresh which devices are exposed."
    ]
}
private coerceSettingValue(String key, value, String type) {
    if (value == null) {
        throw new IllegalArgumentException("Setting '${key}' value cannot be null")
    }
    switch (type) {
        case "bool":
            if (value instanceof Boolean) return value
            def s = value.toString().toLowerCase()
            if (s == "true") return true
            if (s == "false") return false
            throw new IllegalArgumentException("Setting '${key}' expects a boolean (true/false), got: ${_describeValueForError(value)}")
        case "number":
            if (value instanceof Number) return value
            def s = value.toString()
            if (s.isInteger()) return s.toInteger()
            if (s.isLong()) return s.toLong()
            if (s.isBigDecimal()) return s.toBigDecimal()
            throw new IllegalArgumentException("Setting '${key}' expects a number, got: ${_describeValueForError(value)}")
        case "enum":
            return value.toString()
        default:
            return value
    }
}
def getPackageSourceBase() {
    return "https://raw.githubusercontent.com/kingpanther13/Hubitat-local-MCP-server"
}
def _reanchorToRef(location, String base, String ref) {
    if (!(location instanceof String) || !location.trim()) return null
    def loc = location.trim()
    def rel = loc.replaceFirst(/^https?:\/\/[^\/]+\/[^\/]+\/[^\/]+\/[^\/]+\//, '')
    if (rel == loc || !rel) return null
    return "${base}/${ref}/${rel}".toString()
}
def _bundleArtifactUrlForRef(location, String base, String ref) {
    if (!(location instanceof String) || !location.trim() || !ref) return null
    def loc = location.trim()
    def rel = loc.replaceFirst(/^https?:\/\/[^\/]+\/[^\/]+\/[^\/]+\/[^\/]+\//, '')
    if (rel == loc || !rel) return null
    def baseName = rel.tokenize('/').last()
    def keyPath = (ref ==~ /[0-9a-f]{40}/) ? "shas/${ref}" : "branches/${ref}"
    return "${base}/bundle-artifacts/${keyPath}/${baseName}".toString()
}
def _artifactSizeMarker(String artifactUrl) {
    try {
        def r = _httpFetchUrl("${artifactUrl}.size")
        def body = r?.body?.toString()?.trim()
        return ((r?.status as Integer) == 200 && body ==~ /\d+/) ? (body as Long) : null
    } catch (Exception e) {
        mcpLog("warn", "developer-mode", "_artifactSizeMarker: probe of ${artifactUrl}.size failed (${e.toString()}) -- treating as no artifact")
        return null
    }
}
def _bundleArtifactExists(String artifactUrl) {
    return _artifactSizeMarker(artifactUrl) != null
}
def _parseIncludeDirectives(String source) {
    def tokens = []
    def seen = [] as Set
    def matcher = (source =~ /(?m)^[ \t]*#include[ \t]+([A-Za-z0-9_]+\.[A-Za-z0-9_]+)[ \t]*$/)
    while (matcher.find()) {
        def tok = matcher.group(1)
        if (!seen.contains(tok)) { seen << tok; tokens << tok }
    }
    return tokens
}
def _resolveSelfAppClassId() {
    try {
        def responseText = hubInternalGet("/hub2/userAppTypes")
        if (!responseText) return null
        def parsed = new groovy.json.JsonSlurper().parseText(responseText)
        if (!(parsed instanceof List)) return null
        def match = parsed.find { it?.namespace == "mcp" && it?.name == "MCP Rule Server" }
        return match?.id?.toString()
    } catch (Exception e) {
        mcpLog("warn", "hub-admin", "_resolveSelfAppClassId: self app-class lookup failed (${e.toString()}) -- caller must handle the unavailable class identity")
        return null
    }
}
def toolUpdatePackage(args) {
    if (!settings.enableDeveloperMode) {
        throw new IllegalArgumentException("Developer Mode tools are disabled. Enable 'Developer Mode Tools' in MCP rule app settings to use hub_update_package.")
    }
    def ref = args?.ref
    if (!(ref instanceof String) || !ref.trim()) {
        throw new IllegalArgumentException("ref is required: a branch, tag, or commit SHA to deploy (e.g. 'main' or a PR head SHA).")
    }
    ref = ref.trim()
    if (args?.dryRun == true) return _updatePackageBody(args as Map, ref, true)
    requireDestructiveConfirm(args?.confirm)
    long startedAt = now()
    String requestId = "pkg-${java.util.UUID.randomUUID()}".toString()
    def storedArgs = [ref: ref, confirm: true]
    if (args?.baseUrl instanceof String && args.baseUrl.trim()) storedArgs.baseUrl = args.baseUrl.trim()
    Map refusal = null
    synchronized (WRITE_RESERVATION_LOCK) {
        _packageSweepMarkerLocked()
        def inFlight = _writeStateValueLocked("packageDeployInFlight")
        if (inFlight instanceof Map) {
            def summary = [ref: inFlight.ref, requestId: inFlight.requestId,
                           startedAt: inFlight.startedAt]
            if (inFlight.startedAt != null) {
                try { summary.elapsedMs = now() - (inFlight.startedAt as Long) }
                catch (Exception ignored) { }
            }
            refusal = [
                success: false, isError: true, status: "duplicate_in_flight",
                inFlight: summary,
                error: "A package deploy (ref '${inFlight.ref}') is already running on this hub. Nothing was changed.",
                note: "Do not re-run the deploy. Watch hub_get_info.lastSelfDeploy for a record whose requestId matches the original acceptance response."
            ]
        }
        if (refusal == null) {
            _writeStateSetLocked("packageDeployInFlight", [
                requestId: requestId, ref: ref, startedAt: startedAt,
                phase: "queued", expiresAt: startedAt + _packageDeployRecoveryMs(),
                args: storedArgs
            ])
        }
    }
    if (refusal != null) return refusal
    try {
        runIn(1, "runPackageDeploy", [data: [requestId: requestId]])
    } catch (Exception scheduleErr) {
        synchronized (WRITE_RESERVATION_LOCK) {
            def current = _writeStateValueLocked("packageDeployInFlight")
            if (current instanceof Map && current.requestId?.toString() == requestId) {
                _writeStateSetLocked("packageDeployInFlight", null)
                try { atomicState.remove("packageDeployInFlight") } catch (Exception ignored) { }
            }
        }
        return [success: false, isError: true, status: "schedule_failed", ref: ref,
                error: "Package deploy could not be scheduled: ${scheduleErr.message}. Nothing was changed.",
                note: "The in-flight marker was released, so this call is safe to retry with the same ref. If it keeps failing, the hub's scheduler is refusing jobs -- check hub_get_logs, then deploy each app with hub_update_app instead."]
    }
    return [
        success: true,
        status: "in_progress",
        ref: ref,
        requestId: requestId,
        startedAt: startedAt,
        message: "Package deploy accepted and is running in the background.",
        note: "Do not submit it again. Read hub_get_info.lastSelfDeploy until its requestId matches this response; success/error then carries the final outcome."
    ]
}
def runPackageDeploy(Map job = [:]) {
    String requestId = job?.requestId?.toString()
    Map marker = null
    synchronized (WRITE_RESERVATION_LOCK) {
        def current = _writeStateValueLocked("packageDeployInFlight")
        if (current instanceof Map && current.requestId?.toString() == requestId
                && current.args instanceof Map && current.ref
                && !_writeExecutionLiveLocked(requestId)) {
            marker = [:] + (current as Map)
            marker.phase = "running"
            marker.expiresAt = now() + _packageDeployRecoveryMs()
            _writeStateSetLocked("packageDeployInFlight", marker)
            LIVE_WRITE_EXECUTIONS.add(requestId)
        }
    }
    if (marker == null) return
    def result = null
    try {
        Map workerContext = [requestId: requestId, packageRef: marker.ref.toString()]
        result = _updatePackageBody(marker.args as Map, marker.ref.toString(), false, workerContext)
        def last = atomicState.lastSelfDeploy
        if (!(last instanceof Map) || last.requestId?.toString() != requestId) {
            atomicState.lastSelfDeploy = [
                success: result?.success == true,
                error: result?.success == true ? null : (result?.error ?: result?.message ?: "Package deploy failed"),
                sourceMode: "package",
                ref: marker.ref,
                requestId: requestId,
                packageResult: result,
                at: now()
            ]
        }
    } catch (Exception e) {
        mcpLog("error", "developer-mode", "Background package deploy for ref ${marker.ref} failed: ${e.message}")
        def last = atomicState.lastSelfDeploy
        if (!(last instanceof Map) || last.requestId?.toString() != requestId) {
            atomicState.lastSelfDeploy = [success: false, error: e.message ?: e.toString(),
                                          sourceMode: "package", ref: marker.ref,
                                          requestId: requestId, at: now()]
        }
    } finally {
        synchronized (WRITE_RESERVATION_LOCK) {
            try {
                def current = _writeStateValueLocked("packageDeployInFlight")
                if (current instanceof Map && current.requestId?.toString() == requestId) {
                    _writeStateSetLocked("packageDeployInFlight", null)
                    atomicState.remove("packageDeployInFlight")
                }
            } catch (Exception ignored) {
            } finally {
                LIVE_WRITE_EXECUTIONS.remove(requestId)
            }
        }
    }
}
def _updatePackageBody(Map args, String ref, boolean dryRun, Map packageWorkerContext = null) {
    def base = (args?.baseUrl instanceof String && args.baseUrl.trim())
        ? args.baseUrl.trim().replaceAll('/+$', '')
        : getPackageSourceBase()
    def appUrl = "${base}/${ref}/hubitat-mcp-server.groovy".toString()
    def manifestUrl = "${base}/${ref}/packageManifest.json".toString()
    def manifestText
    try {
        manifestText = _fetchSourceFromUrl(manifestUrl)
    } catch (Exception e) {
        return [
            success: false, aborted: true, abortReason: "manifest_fetch_failed", ref: ref, manifestUrl: manifestUrl,
            error: "Failed to fetch packageManifest.json at ref '${ref}' (${manifestUrl}): ${e.message ?: e.toString()}. Nothing was changed."
        ]
    }
    def manifest
    try {
        manifest = new groovy.json.JsonSlurper().parseText(manifestText)
    } catch (Exception e) {
        manifest = null
    }
    if (!(manifest instanceof Map)) {
        return [
            success: false, aborted: true, abortReason: "manifest_unparseable", ref: ref, manifestUrl: manifestUrl,
            error: "packageManifest.json at ref '${ref}' was not a JSON object. Nothing was changed."
        ]
    }
    def manifestBundles = (manifest.bundles instanceof List) ? manifest.bundles : []
    def manifestApps = (manifest.apps instanceof List) ? manifest.apps : []
    boolean inlined = manifestBundles.isEmpty() && !manifestApps.isEmpty() &&
        manifestApps.every { it?.location instanceof String && it.location.contains("/bundle-artifacts/") }
    def includeTokens = []
    def plannedBundles = []
    if (!inlined) {
        def bundlePlan = _planPackageBundles(manifestBundles, base, ref, appUrl)
        if (bundlePlan.abort) return bundlePlan.abort
        includeTokens = bundlePlan.includes
        plannedBundles = bundlePlan.bundles
    }
    def appTypes
    try {
        def typesText = hubInternalGet("/hub2/userAppTypes")
        appTypes = typesText ? new groovy.json.JsonSlurper().parseText(typesText) : null
    } catch (Exception e) {
        appTypes = null
    }
    if (!(appTypes instanceof List)) {
        return [
            success: false, aborted: true, abortReason: "app_class_unresolved", ref: ref,
            error: "Could not list Apps Code classes via /hub2/userAppTypes to resolve the manifest's apps. Nothing was changed; the app remains updatable via hub_update_app."
        ]
    }
    def plannedApps = []
    for (a in manifestApps) {
        def match = appTypes.find { it?.namespace == a?.namespace && it?.name == a?.name }
        def classId = match?.id?.toString()
        def url = inlined ? _bundleArtifactUrlForRef(a?.location, base, ref) : _reanchorToRef(a?.location, base, ref)
        if (!classId || !url) {
            return [
                success: false, aborted: true, abortReason: "app_class_unresolved", ref: ref,
                error: "Could not resolve app '${a?.namespace}:${a?.name}' (class id: ${classId ?: 'unresolved'}, url: ${url ?: 'unusable location'}). Nothing was changed; the app remains updatable via hub_update_app."
            ]
        }
        def entry = [
            name: a?.name, namespace: a?.namespace, classId: classId, url: url,
            isSelf: (a?.namespace == "mcp" && a?.name == "MCP Rule Server")
        ]
        if (inlined) {
            def artifact = _planAppArtifact(a.name?.toString(), a.location.trim(), url, ref)
            if (artifact.abort) return artifact.abort
            entry.url = artifact.url
            entry.source = artifact.source
            entry.expectedBytes = artifact.expectedBytes
        }
        plannedApps << entry
    }
    def orderedApps = plannedApps.findAll { !it.isSelf } + plannedApps.findAll { it.isSelf }
    if (dryRun) {
        return [
            success: true, dryRun: true, ref: ref, appUrl: appUrl, includes: includeTokens,
            plannedBundles: plannedBundles, plannedApps: orderedApps,
            message: "Dry run: would install ${plannedBundles.size()} bundle(s) then deploy ${orderedApps.size()} app(s) (self app last) to ref ${ref}. No changes made."
        ]
    }
    def verifiedSources = [:]
    if (inlined) {
        for (a in orderedApps) {
            def src
            try {
                src = _fetchSourceFromUrl(a.url)
            } catch (Exception e) {
                return [
                    success: false, aborted: true, abortReason: "app_artifact_fetch_failed", ref: ref, app: a.name, url: a.url,
                    error: "Failed to fetch ${a.name} from ${a.url}: ${e.message ?: e.toString()}. Nothing was changed."
                ]
            }
            long actualBytes = src.getBytes("UTF-8").length
            if (actualBytes != (a.expectedBytes as Long)) {
                return [
                    success: false, aborted: true, abortReason: "app_artifact_size_mismatch", ref: ref, app: a.name, url: a.url,
                    expectedBytes: a.expectedBytes, actualBytes: actualBytes,
                    error: "${a.name} from ${a.url} is ${actualBytes} bytes but its .size marker records ${a.expectedBytes} (truncated download or a publish in progress). Nothing was changed; retry in a minute."
                ]
            }
            if (!_parseIncludeDirectives(src).isEmpty()) {
                return [
                    success: false, aborted: true, abortReason: "app_artifact_not_inlined", ref: ref, app: a.name, url: a.url,
                    error: "${a.name} from ${a.url} still has #include directives, and the manifest declares no bundle to deliver them, so it would not compile. Nothing was changed."
                ]
            }
            verifiedSources.put(a.classId, src)
        }
    }
    def bundleResults = []
    for (b in plannedBundles) {
        def r
        try {
            r = toolInstallBundle([importUrl: b.url, confirm: true])
        } catch (Exception e) {
            mcpLog("warn", "developer-mode", "hub_update_package: bundle ${b.url} install threw: ${e.toString()}")
            return [
                success: false, aborted: true, abortReason: "bundle_install_threw", ref: ref, bundles: bundleResults,
                error: "Bundle ${b.name ?: b.url} failed to install: ${e.message ?: e.toString()}. Apps NOT touched -- they remain as-is and updatable via hub_update_app."
            ]
        }
        def ok = (r?.success == true)
        bundleResults << [name: b.name, url: b.url, source: b.source, success: ok, error: (ok ? null : (r?.error ?: r?.message))]
        if (!ok) {
            return [
                success: false, aborted: true, abortReason: "bundle_install_failed", ref: ref, bundles: bundleResults,
                error: "Bundle ${b.name ?: b.url} install reported failure: ${r?.error ?: r?.message ?: 'unknown'}. Apps NOT touched -- they remain as-is and updatable via hub_update_app."
            ]
        }
    }
    def appResults = []
    for (a in orderedApps) {
        def r
        try {
            def updateArgs = inlined ? [appId: a.classId, source: verifiedSources.remove(a.classId), sourceOrigin: "published", confirm: true]
                                     : [appId: a.classId, importUrl: a.url, confirm: true]
            r = _toolUpdateAppCode(updateArgs, a.isSelf ? packageWorkerContext : null)
        } catch (Exception e) {
            if (a.isSelf) {
                appResults << [name: a.name, namespace: a.namespace, classId: a.classId, isSelf: true, success: false, error: (e.message ?: e.toString())]
                return [
                    success: false, partial: true, abortReason: "app_update_threw", ref: ref,
                    bundles: bundleResults, apps: appResults,
                    error: "Bundle(s) and other apps installed, but the self app update call did not return cleanly (likely the self-update recompile): ${e.message ?: e.toString()}. Verify with hub_get_source; re-run hub_update_app(importUrl) if needed."
                ]
            }
            mcpLog("warn", "developer-mode", "hub_update_package: app ${a.namespace}:${a.name} update threw: ${e.toString()}")
            return [
                success: false, aborted: true, abortReason: "app_update_threw", ref: ref,
                bundles: bundleResults, apps: appResults,
                error: "App ${a.namespace}:${a.name} update threw before the self app was touched: ${e.message ?: e.toString()}. The self (server) app was NOT touched -- it remains as-is and updatable via hub_update_app."
            ]
        }
        def ok = (r?.success == true)
        appResults << [name: a.name, namespace: a.namespace, classId: a.classId, url: a.url, isSelf: a.isSelf, success: ok, app: r]
        if (!ok) {
            if (a.isSelf) {
                mcpLog("warn", "developer-mode", "hub_update_package: ref=${ref} self app update reported failure")
                return [
                    success: false, partial: true, ref: ref, includes: includeTokens, bundles: bundleResults, apps: appResults, app: r,
                    message: "Bundle(s) + other apps installed; the self (server) app update reported failure -- see apps[].app.error. hub_update_app remains available to retry."
                ]
            }
            return [
                success: false, aborted: true, abortReason: "app_update_failed", ref: ref,
                bundles: bundleResults, apps: appResults,
                error: "App ${a.namespace}:${a.name} update reported failure: ${r?.error ?: r?.message ?: 'unknown'}. The self (server) app was NOT touched -- it remains as-is and updatable via hub_update_app."
            ]
        }
    }
    mcpLog("info", "developer-mode", "hub_update_package: ref=${ref} bundles=${bundleResults.size()} apps=${appResults.size()} repaired")
    def result = [
        success: true, ref: ref, includes: includeTokens, bundles: bundleResults, apps: appResults,
        message: "Package repaired to ref ${ref}: ${bundleResults.size()} bundle(s) + ${appResults.size()} app(s) deployed (self app last)."
    ]
    if (bundleResults.any { it.source == "manifest-current" }) {
        if (ref == "main") {
            result.bundleFreshnessWarning = "The per-ref artifact probe failed, so the bundle leg installed the manifest's branches/main zip directly -- for ref=main that is the correct, current bundle (the same bytes HPM users install). Noted only because the probe failing may indicate a transient raw.githubusercontent issue."
            mcpLog("warn", "developer-mode", "hub_update_package: ref=main artifact probe failed; installed the manifest's branches/main zip directly (correct bytes for main)")
        } else {
            result.bundleFreshnessWarning = "Ref '${ref}': no bundle-artifacts zip was found for this ref, so the bundle leg installed CURRENT MAIN's bundle (the manifest's branches/main zip). That is only correct if this ref's libraries match current main. If this ref changed library code, push it to this repo (publish-bundle-artifact stores a fresh zip per push, keyed by branch and full SHA) and re-run."
            mcpLog("warn", "developer-mode", "hub_update_package: non-main ref '${ref}' fell back to current main's bundle -- wrong if the ref changed library code")
        }
    } else if (bundleResults.any { it.source == "committed-at-ref" }) {
        result.bundleFreshnessWarning = "Ref '${ref}' (legacy manifest): no bundle-artifacts zip was found for this ref, so the bundle leg installed the zip COMMITTED at the ref. That is only stale if this ref CHANGED library code without rebuilding the zip."
        mcpLog("warn", "developer-mode", "hub_update_package: legacy ref '${ref}' fell back to the committed bundle zip -- stale if the ref changed library code")
    }
    if (orderedApps.any { it.source == "manifest-current" }) {
        result.artifactFreshnessWarning = "No app artifact was found under ${base} for ref=main, so the apps were installed from the manifest's own branches/main build -- the same files HPM users install."
        mcpLog("warn", "developer-mode", "hub_update_package: ref=main app artifact probe missed under ${base}; installed the manifest's branches/main build")
    }
    return result
}
private Map _planPackageBundles(List manifestBundles, String base, String ref, String appUrl) {
    def appSource
    try {
        appSource = _fetchSourceFromUrl(appUrl)
    } catch (Exception e) {
        return [abort: [
            success: false, aborted: true, abortReason: "app_source_fetch_failed", ref: ref, appUrl: appUrl,
            error: "Failed to fetch app source at ref '${ref}' (${appUrl}): ${e.message ?: e.toString()}. Nothing was changed."
        ]]
    }
    def includeTokens = _parseIncludeDirectives(appSource)
    def plannedBundles = []
    for (b in manifestBundles) {
        def loc = (b?.location instanceof String) ? b.location.trim() : null
        def entry
        if (loc && loc.contains("/bundle-artifacts/")) {
            entry = [name: (b?.name ?: b?.id), url: loc, source: "manifest-current"]
        } else {
            def url = _reanchorToRef(loc, base, ref)
            if (!url) {
                return [abort: [
                    success: false, aborted: true, abortReason: "bundle_location_unusable", ref: ref,
                    error: "Bundle '${b?.name ?: b?.id ?: '?'}' in packageManifest.json has an unusable location '${b?.location}' (expected a scheme://host/owner/repo/ref/<path> raw URL or a bundle-artifacts URL). Nothing was changed."
                ]]
            }
            entry = [name: (b?.name ?: b?.id), url: url, source: "committed-at-ref"]
        }
        def artifactUrl = _bundleArtifactUrlForRef(loc, base, ref)
        if (artifactUrl && _bundleArtifactExists(artifactUrl)) {
            entry.url = artifactUrl
            entry.source = "bundle-artifacts"
        }
        if (entry.source == "manifest-current" && ref != null && (ref.toString().trim() ==~ /(?i)^[0-9a-f]{7,40}$/)) {
            return [abort: [
                success: false, aborted: true, abortReason: "no_bundle_artifact_for_ref", ref: ref,
                bundle: (b?.name ?: b?.id), artifactUrlProbed: artifactUrl,
                error: "No per-ref bundle artifact exists for ref '${ref}' (probed ${artifactUrl ?: 'n/a'}); the manifest's bundle points at branches/main, so installing it would deliver MAIN's libraries, not this ref's. Pass the FULL 40-char commit SHA of a PUSHED commit (not an abbreviation), or push the branch so its bundle artifact is built. Nothing was changed."
            ]]
        }
        plannedBundles << entry
    }
    if (!includeTokens.isEmpty() && plannedBundles.isEmpty()) {
        return [abort: [
            success: false, aborted: true, abortReason: "bundle_required_but_undeclared", ref: ref, includes: includeTokens,
            error: "App source #includes ${includeTokens.size()} library(ies) (${includeTokens.join(', ')}) but packageManifest.json at ref '${ref}' declares no bundle to deliver them. A bundle-less deploy would leave the #includes unresolved and the app would not compile. Nothing was changed."
        ]]
    }
    return [includes: includeTokens, bundles: plannedBundles]
}
private Map _planAppArtifact(String name, String location, String artifactUrl, String ref) {
    def bytes = _artifactSizeMarker(artifactUrl)
    if (bytes != null) return [url: artifactUrl, source: "bundle-artifacts", expectedBytes: bytes]
    if (ref == "main" && location != artifactUrl) {
        bytes = _artifactSizeMarker(location)
        if (bytes != null) return [url: location, source: "manifest-current", expectedBytes: bytes]
    }
    return [abort: [
        success: false, aborted: true, abortReason: "no_app_artifact_for_ref", ref: ref, app: name, artifactUrlProbed: artifactUrl,
        error: "No built artifact exists for app '${name}' at ref '${ref}' (probed ${artifactUrl}.size). Pass the FULL 40-char SHA of a pushed commit, or a branch pushed to this repo -- the publish workflow builds both on every push. Nothing was changed."
    ]]
}
def _getAllToolDefinitions_partSelfAdmin() {
    return [
        [
            name: "hub_update_mcp_settings",
            description: "Update one or more of the MCP rule app's own settings (toggles, log levels, tuning, the device-access scope) in place — self-administer the app without the Hubitat UI. Gated on enableDeveloperMode + the Write master + confirm=true + a recent backup; every successful write is logged at WARN for audit.[[FLAT_TRIM]] Changing an enable* toggle or useGateways reshapes tools/list, and changing selectedDevices changes which devices are visible, so MCP clients may need to reconnect to refresh cached schemas / device visibility.[[/FLAT_TRIM]]",
            inputSchema: [
                type: "object",
                properties: [
                    settings: [type: "object", description: "Map of setting key → new value (e.g. {\"mcpLogLevel\":\"warn\",\"enableCustomRuleEngine\":true}). Unlisted keys are rejected. bypassDeviceAllowlist (bool, default OFF): DANGEROUS escape hatch — when ON native device reads, writes, commands, inventory, health, dependents, swaps and replacements reach ANY hub device by id, IGNORING selectedDevices. Allowlisted keys: mcpLogLevel, debugLogging, maxCapturedStates, loopGuardMax, loopGuardWindowSec, enableRead, enableCustomRuleEngine, useGateways, enableMandatoryBPS, bypassDeviceAllowlist, maxConcurrentWrites, backupEveryRuleWrite, enableLocalAccess, enableCloudAccess, redactAccessTokens, selectedDevices.[[FLAT_TRIM]] enableLocalAccess / enableCloudAccess (bool): allow requests over the LAN / Hubitat cloud endpoint; a call cannot turn off the connection it arrived on.[[/FLAT_TRIM]] mcpLogLevel: debug|info|warn|error. maxConcurrentWrites: integer 0-100[[FLAT_TRIM]] (default 2; 0 disables the server-side all-write concurrency cap)[[/FLAT_TRIM]]. backupEveryRuleWrite (bool, default OFF): ON takes a fresh File Manager backup before every native-app edit instead of reusing a same-app baseline for one hour. bypassDeviceAllowlist is independent of Developer Mode; see hub_get_tool_guide(section='hub_admin_write_system'). selectedDevices = the device-access scope[[FLAT_TRIM]]: {mode:replace|add|remove, ids:[device id strings]}; a bare array is shorthand for a destructive replace[[/FLAT_TRIM]] — see hub_get_tool_guide(section='hub_admin_write_system') for per-mode semantics."],
                    confirm: [type: "boolean", description: "REQUIRED: must be true to confirm the operation"]
                ],
                required: ["settings", "confirm"]
            ]
        ],
        [
            name: "hub_update_package",
            description: """Developer Mode self-deploy: full HPM-repair of the MCP package at a git ref in one call -- OVERRIDES whatever is installed, anchored to packageManifest.json AT `ref` so an UNMERGED PR installs.[[FLAT_TRIM]] (Plain HPM Repair only reads the PUBLISHED manifest, so it can't reach an unmerged PR's artifacts.)[[/FLAT_TRIM]]

Gated on enableDeveloperMode[[FLAT_TRIM]] (the tool is hidden from tools/list when Developer Mode is off)[[/FLAT_TRIM]] + the Write master + confirm=true + a recent backup. Use dryRun=true to fetch + parse + plan with ZERO writes (no confirm/backup needed)[[FLAT_TRIM]] and see exactly which bundles and apps would deploy[[/FLAT_TRIM]].

A real deploy is accepted quickly with `status: "in_progress"` and runs in the background; do NOT submit it again while one is in flight.[[FLAT_TRIM]] The background run uses Hubitat's own scheduler, so neither the cloud relay nor the MCP client's request timeout has to stay open for the minutes-long repair; a concurrent second deploy is refused. Poll hub_get_info.lastSelfDeploy until its `requestId` matches the acceptance response; that bound record's `success`/`error` fields carry the outcome. No client extension or custom token is required.[[/FLAT_TRIM]]
""",
            inputSchema: [
                type: "object",
                properties: [
                    ref: [type: "string", description: "Branch, tag, or commit SHA to deploy (e.g. 'main' or a PR head SHA)."],
                    dryRun: [type: "boolean", description: "OPTIONAL. When true, report the deploy plan with NO writes (skips the confirm/backup gate). Default false."],
                    baseUrl: [type: "string", description: "OPTIONAL raw-source base override (no trailing slash); defaults to the canonical repo.[[FLAT_TRIM]] Per-call URLs are built as <baseUrl>/<ref>/<path>. Use for forks / CI branches on a different remote.[[/FLAT_TRIM]]"],
                    confirm: [type: "boolean", description: "REQUIRED for a real deploy (omit for dryRun). Must be true; confirms a recent backup exists and the user approved the self-deploy."],
                    args: [type: "object"]
                ],
                required: ["ref"]
            ]
        ],
    ]
}
