private Map _mrtrCloneNativeAppSlice(Map rec, Map outerArgs) {
    Map args = _mrtrLeafArguments(rec.outerTool?.toString(), rec.leafTool?.toString(), outerArgs) as Map
    Map cp = (rec.checkpoint instanceof Map) ? _mrtrCopyMap(rec.checkpoint as Map) : null
    if (cp == null) {
        requireDestructiveConfirm(args?.confirm as Boolean)
        def rawSource = (args?.sourceAppId != null) ? args.sourceAppId : args?.appId
        if (rawSource == null) throw new IllegalArgumentException("sourceAppId (or appId) is required")
        Integer sourceAppId = normalizeRuleId(rawSource)
        String newName = args?.newName?.toString()?.trim()
        def sourceCfg
        try { sourceCfg = _rmFetchConfigJson(sourceAppId) }
        catch (Exception sourceErr) {
            mcpLog("warn", "rm-native", "hub_clone_native_app: source ${sourceAppId} config fetch failed: ${sourceErr.message}")
            sourceCfg = null
        }
        if (!sourceCfg?.app) throw new IllegalArgumentException("Source app ${sourceAppId} not found or unreadable")
        String sourceLabel = sourceCfg.app.label?.toString()
        Integer parentAppId = null
        try {
            parentAppId = sourceCfg.app.parentAppId != null ? sourceCfg.app.parentAppId.toString() as Integer : null
        } catch (NumberFormatException ignored) {
            mcpLog("warn", "rm-native", "hub_clone_native_app: source ${sourceAppId} parentAppId not numeric: ${sourceCfg.app.parentAppId}")
        }
        if (parentAppId == null) {
            throw new IllegalArgumentException("Source app ${sourceAppId} has no numeric parentAppId. MCP cannot safely discover its clone; pass a child of the target parent app.")
        }
        _requireUnprotectedAppMutation(parentAppId, "clone or import a child app under")
        Map snapshot = _appClonerSnapshotChildren(parentAppId)
        if (snapshot.isError == true) return snapshot
        def preIds = snapshot.ids
        def initRes = _appClonerInit(sourceAppId)
        cp = [phase: "clone_clicks", clonerAppId: initRes.clonerAppId,
              referrer: initRes.referrer, configUrl: initRes.configUrl,
              sourceAppId: sourceAppId, sourceLabel: sourceLabel,
              parentAppId: parentAppId, preIds: preIds, newName: newName,
              stageDisabled: args?.stageDisabled == true]
        return _mrtrControl("clone_native_app", cp)
    }
    Integer clonerAppId = cp.clonerAppId as Integer
    try {
        if (cp.phase != "stage_disable") _requireUnprotectedAppMutation(cp.parentAppId, "clone or import a child app under")
        if (cp.phase == "clone_clicks") {
            _appClonerClickClone(clonerAppId, cp.referrer?.toString(), cp.configUrl?.toString())
            cp.phase = "clone_commit"
            return _mrtrControl("clone_native_app", cp)
        }
        if (cp.phase == "clone_commit") {
            _appClonerCommitImportRule(clonerAppId, cp.sourceAppId as Integer,
                cp.newName?.toString(), cp.referrer?.toString(), cp.configUrl?.toString())
            Integer newAppId = _appClonerDiscoverNewChild(cp.parentAppId as Integer,
                (cp.preIds ?: []) as Set, cp.sourceLabel?.toString(), cp.newName?.toString())
            String note = newAppId
                ? "Cloned source ${cp.sourceAppId} -> new app ${newAppId}${cp.newName ? " (renamed to '${cp.newName}')" : ""}. Use hub_set_native_app (or hub_set_rule for RM rules) to further customize."
                : "Clone fired but no new child appeared under parent ${cp.parentAppId}. Re-check via hub_list_apps (scope='instances') shortly."
            def baseResult = [success: newAppId != null, sourceAppId: cp.sourceAppId,
                              clonerAppId: clonerAppId, newAppId: newAppId, note: note]
            if (newAppId == null) {
                baseResult.isError = true
                baseResult.error = note
                if (cp.stageDisabled == true) _appClonerStagingDiscoveryMiss(baseResult, "clone")
                _appClonerCleanup(clonerAppId)
                return baseResult
            }
            if (cp.stageDisabled != true) {
                _appClonerCleanup(clonerAppId)
                return baseResult
            }
            def stagePlan = _appClonerStagePlan(newAppId)
            cp.phase = "stage_disable"
            cp.newAppId = newAppId
            cp.stageTargets = stagePlan.targets
            cp.stageFailures = stagePlan.failures
            cp.stagedDisabled = []
            cp.baseResult = baseResult
            return _mrtrControl("clone_native_app", cp)
        }
        if (cp.phase == "stage_disable") return _mrtrAppClonerStageSlice(cp, "clone")
        throw new IllegalStateException("Unknown clone continuation phase '${cp.phase}'")
    } catch (Exception e) {
        try { _appClonerCleanup(clonerAppId) } catch (Exception ignored) { }
        throw e
    }
}
private Map _mrtrImportNativeAppSlice(Map rec, Map outerArgs) {
    Map args = _mrtrLeafArguments(rec.outerTool?.toString(), rec.leafTool?.toString(), outerArgs) as Map
    Map cp = (rec.checkpoint instanceof Map) ? _mrtrCopyMap(rec.checkpoint as Map) : null
    if (cp == null) {
        requireDestructiveConfirm(args?.confirm as Boolean)
        if (args?.parentHintAppId == null) {
            throw new IllegalArgumentException("parentHintAppId is required (any existing rule's id under the target parent — used to seed the cloner)")
        }
        Integer parentHintAppId = normalizeRuleId(args.parentHintAppId)
        String newName = args?.newName?.toString()?.trim()
        String jsonContent = args?.jsonContent?.toString()
        if (!jsonContent && args?.fromFile) {
            try { jsonContent = new String(downloadHubFile(args.fromFile.toString()), "UTF-8") }
            catch (Exception e) { throw new IllegalArgumentException("Cannot read fromFile '${args.fromFile}': ${e.message}") }
        }
        if (!jsonContent) throw new IllegalArgumentException("jsonContent or fromFile is required")
        def parsed
        try { parsed = new groovy.json.JsonSlurper().parseText(jsonContent) }
        catch (Exception e) { throw new IllegalArgumentException("jsonContent is not valid JSON: ${e.message}") }
        def replacements = (parsed instanceof Map) ? parsed.appReplacements : null
        if (!(replacements instanceof Map) || replacements.isEmpty()) {
            throw new IllegalArgumentException("jsonContent does not contain an appReplacements map — not an appCloner export")
        }
        Integer originalSourceId
        try { originalSourceId = ((replacements.keySet() as List)[0]).toString() as Integer }
        catch (Exception e) { throw new IllegalArgumentException("Could not extract original source id from appReplacements: ${e.message}") }
        String originalLabel = replacements.get(originalSourceId.toString())?.appLabel?.toString()
        def hintCfg
        try { hintCfg = _rmFetchConfigJson(parentHintAppId) }
        catch (Exception hintErr) {
            mcpLog("warn", "rm-native", "hub_import_native_app: parentHintAppId ${parentHintAppId} config fetch failed: ${hintErr.message}")
            hintCfg = null
        }
        if (!hintCfg?.app) throw new IllegalArgumentException("parentHintAppId ${parentHintAppId} not found or unreadable")
        Integer parentAppId = null
        try { parentAppId = hintCfg.app.parentAppId?.toString() as Integer }
        catch (NumberFormatException ignored) {
            mcpLog("warn", "rm-native", "hub_import_native_app: parentHintAppId ${parentHintAppId} parentAppId not numeric: ${hintCfg.app.parentAppId}")
        }
        if (parentAppId == null) {
            throw new IllegalArgumentException("parentHintAppId ${parentHintAppId} has no numeric parentAppId — pass a child of the target parent app")
        }
        _requireUnprotectedAppMutation(parentAppId, "clone or import a child app under")
        Map snapshot = _appClonerSnapshotChildren(parentAppId)
        if (snapshot.isError == true) return snapshot
        def preIds = snapshot.ids
        def initRes = _appClonerInit(parentHintAppId)
        Integer clonerAppId = initRes.clonerAppId as Integer
        try {
            String configUrl = initRes.configUrl?.toString()
            _appClonerSubmitForm(clonerAppId, "main", "source", configUrl, configUrl,
                [("settings[ruleUpload]".toString()): jsonContent])
            pauseExecution(2000)
            cp = [phase: "import_commit", clonerAppId: clonerAppId,
                  referrer: configUrl, configUrl: configUrl,
                  parentAppId: parentAppId, preIds: preIds,
                  originalSourceId: originalSourceId, originalLabel: originalLabel,
                  contentLength: jsonContent.length(), newName: newName,
                  stageDisabled: args?.stageDisabled == true]
            return _mrtrControl("import_native_app", cp)
        } catch (Exception e) {
            try { _appClonerCleanup(clonerAppId) } catch (Exception ignored) { }
            throw e
        }
    }
    Integer clonerAppId = cp.clonerAppId as Integer
    try {
        if (cp.phase != "stage_disable") _requireUnprotectedAppMutation(cp.parentAppId, "clone or import a child app under")
        if (cp.phase == "import_commit") {
            _appClonerCommitImportRule(clonerAppId, cp.originalSourceId as Integer,
                cp.newName?.toString(), cp.referrer?.toString(), cp.configUrl?.toString())
            Integer newAppId = _appClonerDiscoverNewChild(cp.parentAppId as Integer,
                (cp.preIds ?: []) as Set, cp.originalLabel?.toString(), cp.newName?.toString())
            String note = newAppId
                ? "Imported '${cp.originalLabel ?: 'app'}' as new app ${newAppId}${cp.newName ? " (renamed to '${cp.newName}')" : ""}. Use hub_set_native_app (or hub_set_rule for RM rules) to further customize."
                : "Import fired but no new child appeared under parent ${cp.parentAppId}. Re-check via hub_list_apps (scope='instances') shortly."
            def baseResult = [success: newAppId != null, clonerAppId: clonerAppId,
                              newAppId: newAppId, originalSourceId: cp.originalSourceId,
                              originalLabel: cp.originalLabel, contentLength: cp.contentLength,
                              note: note]
            if (newAppId == null) {
                baseResult.isError = true
                baseResult.error = note
                if (cp.stageDisabled == true) _appClonerStagingDiscoveryMiss(baseResult, "import")
                _appClonerCleanup(clonerAppId)
                return baseResult
            }
            if (cp.stageDisabled != true) {
                _appClonerCleanup(clonerAppId)
                return baseResult
            }
            def stagePlan = _appClonerStagePlan(newAppId)
            cp.phase = "stage_disable"
            cp.newAppId = newAppId
            cp.stageTargets = stagePlan.targets
            cp.stageFailures = stagePlan.failures
            cp.stagedDisabled = []
            cp.baseResult = baseResult
            return _mrtrControl("import_native_app", cp)
        }
        if (cp.phase == "stage_disable") return _mrtrAppClonerStageSlice(cp, "import")
        throw new IllegalStateException("Unknown import continuation phase '${cp.phase}'")
    } catch (Exception e) {
        try { _appClonerCleanup(clonerAppId) } catch (Exception ignored) { }
        throw e
    }
}
private Map _mrtrAppClonerStageSlice(Map cp, String operationLabel) {
    List targets = (cp.stageTargets instanceof List) ? cp.stageTargets as List : []
    List staged = (cp.stagedDisabled instanceof List) ? cp.stagedDisabled as List : []
    List failures = (cp.stageFailures instanceof List) ? cp.stageFailures as List : []
    Map outcome = _appClonerDisableTargets(targets, now(), staged, failures)
    List remaining = outcome.remaining
    if (remaining) {
        cp.stageTargets = remaining
        cp.stagedDisabled = staged
        cp.stageFailures = failures
        return _mrtrControl("${operationLabel}_native_app".toString(), cp)
    }
    def result = (cp.baseResult instanceof Map) ? ([:] + cp.baseResult) : [:]
    _appClonerFinishStaging(result, cp.newAppId as Integer, outcome)
    _appClonerCleanup(cp.clonerAppId as Integer)
    return result
}
def toolSearchTools(args) {
    def query = args.query
    if (!query?.trim()) return [error: "query is required"]
    _cleanupRetiredToolState()
    def maxResults = args.maxResults != null ? Math.max(0, args.maxResults as Integer) : 5
    def allDefs = null
    String corpusFp = TOOL_SEARCH_CORPUS_FP
    if (corpusFp == null) {
        allDefs = getAllToolDefinitions()
        corpusFp = toolSearchCorpusFingerprint(allDefs)
        TOOL_SEARCH_CORPUS_FP = corpusFp
    }
    def corpus = null
    def docTokensAll = null
    synchronized (TOOL_SEARCH_INDEX) {
        if (TOOL_SEARCH_INDEX.fingerprint != corpusFp || !(TOOL_SEARCH_INDEX.corpus instanceof List) ||
                !(TOOL_SEARCH_INDEX.tokens instanceof List) || TOOL_SEARCH_INDEX.tokens.size() != TOOL_SEARCH_INDEX.corpus.size()) {
            def built = buildToolSearchCorpus(allDefs)
            def tokens = built.collect { bm25Tokenize(_bm25DocText(it)) }
            TOOL_SEARCH_INDEX.clear()
            TOOL_SEARCH_INDEX.putAll([fingerprint: corpusFp, corpus: built, tokens: tokens])
        }
        corpus = TOOL_SEARCH_INDEX.corpus
        docTokensAll = TOOL_SEARCH_INDEX.tokens
    }
    def searchHideByName = getHiddenToolNames()
    def visibleCorpus = []
    def docTokens = []
    corpus.eachWithIndex { entry, i ->
        if (searchHideByName.contains(entry.name)) return
        visibleCorpus << entry
        docTokens << docTokensAll[i]
    }
    def queryTokens = bm25Tokenize(query)
    if (!queryTokens) return [results: [], message: "No searchable terms in query"]
    def scores = bm25Score(docTokens, queryTokens)
    def ranked = []
    scores.eachWithIndex { score, idx ->
        if (score > 0) ranked << [index: idx, score: score]
    }
    ranked.sort { -it.score }
    def seenSearchNames = [] as Set
    ranked = ranked.findAll { r ->
        def nm = visibleCorpus[r.index].name
        if (seenSearchNames.contains(nm)) return false
        seenSearchNames << nm
        return true
    }
    if (ranked.size() > maxResults) ranked = ranked.take(maxResults)
    def gatewayConfig = getGatewayConfig()
    def displayMeta = getToolDisplayMeta()
    def results = ranked.collect { r ->
        def tool = visibleCorpus[r.index]
        def entry = [
            tool: _externalToolName(tool.name as String),
            description: _withGuideFirst(tool.name as String, tool.description as String),
            relevance: Math.round(r.score * 100) / 100.0
        ]
        if (tool.title) entry.title = tool.title
        if (tool.gateway) {
            def config = gatewayConfig.get(tool.gateway)
            def intro = _visibleGatewayIntro(tool.gateway, gatewayConfig, searchHideByName, displayMeta)
            entry.description = _withGuideFirst(tool.name as String, "${config.summaries.get(tool.name) ?: ''} [${intro}]".toString())
            entry.gateway = _externalToolName(tool.gateway as String)
            entry.callAs = "Call via ${_externalToolName(tool.gateway as String)}(tool=\"${_externalToolName(tool.name as String)}\", args={...})"
        } else {
            entry.callAs = "Call directly: ${_externalToolName(tool.name as String)}({...})"
        }
        return entry
    }
    return [
        query: query,
        resultsCount: results.size(),
        totalToolsSearched: visibleCorpus*.name.toSet().size(),
        results: results
    ]
}
def toolSearchCorpusFingerprint(List defs = null) {
    long h = 17L
    def displayMeta = getToolDisplayMeta()
    applyDescriptionTransform(defs ?: getAllToolDefinitions(), false, false).each { toolDef ->
        h = _fpField(h, toolDef.name as String)
        h = _fpField(h, displayMeta[toolDef.name]?.title)
        h = _fpField(h, toolDef.description)
        h = _fpField(h, toolDef.inputSchema?.properties?.keySet()?.join(','))
    }
    getGatewayConfig().each { gwName, config ->
        h = _fpField(h, gwName as String)
        h = _fpField(h, config.description)
        config.tools.each { toolName ->
            h = _fpField(h, toolName as String)
            h = _fpField(h, config.summaries?."${toolName}")
            h = _fpField(h, config.searchHints?."${toolName}")
        }
    }
    h = _fpField(h, bm25Tokenize(_bm25DocText(
        [name: 'hub_x-1', title: 'A_b', description: 'cd', params: 'ef', hints: 'gh',
         gateway: 'ij'])).join(','))
    return Long.toString(h)
}
private String _bm25DocText(entry) {
    return "${entry.name} ${entry.title ?: ''} ${entry.description} ${entry.params ?: ''} ${entry.hints ?: ''}"
}
private long _fpField(long h, value) {
    String s = (value == null) ? "" : value.toString()
    h = h * 31L + s.length()
    return h * 31L + s.hashCode()
}
private buildToolSearchCorpus(List defs = null) {
    def gatewayConfig = getGatewayConfig()
    def proxiedNames = gatewayConfig.values().collectMany { it.tools } as Set
    def allDefs = applyDescriptionTransform(defs ?: getAllToolDefinitions(), false, false)
    def allDefsMap = allDefs.collectEntries { [(it.name): it] }
    def displayMeta = getToolDisplayMeta()
    def corpus = []
    allDefs.each { toolDef ->
        if (!proxiedNames.contains(toolDef.name)) {
            def params = toolDef.inputSchema?.properties?.keySet()?.join(" ") ?: ""
            corpus << [name: toolDef.name, title: displayMeta[toolDef.name]?.title, description: toolDef.description?.replaceAll(/\n+/, ' ')?.trim(), params: params, gateway: null]
        }
    }
    gatewayConfig.each { gwName, config ->
        config.tools.each { toolName ->
            def summary = config.summaries[toolName] ?: ""
            def hints = config.searchHints?."${toolName}" ?: ""
            def fullDef = allDefsMap[toolName]
            def params = fullDef?.inputSchema?.properties?.keySet()?.join(" ") ?: ""
            corpus << [name: toolName, title: displayMeta[toolName]?.title, description: "${summary} [${config.description}]", params: params, hints: hints, gateway: gwName]
        }
    }
    return corpus
}
private bm25Tokenize(String text) {
    if (!text) return []
    return text.toLowerCase().split(/[^a-z0-9]+/).findAll { it.length() > 1 }
}
private String _bm25Key(String token) {
    return "t_${token}".toString()
}
private bm25Score(List<List<String>> docTokens, List<String> queryTokens) {
    def k1 = 1.5
    def b = 0.75
    def n = docTokens.size()
    if (n == 0) return []
    def docLengths = docTokens.collect { it.size() }
    def avgDl = docLengths.sum() / (double) n
    if (avgDl == 0) return new double[n] as List
    def df = [:]
    docTokens.each { tokens ->
        tokens.toSet().each { token ->
            def k = _bm25Key(token)
            df.put(k, (df.get(k) ?: 0) + 1)
        }
    }
    def scores = new double[n]
    docTokens.eachWithIndex { tokens, docIdx ->
        def tf = [:]
        tokens.each { t -> def k = _bm25Key(t); tf.put(k, (tf.get(k) ?: 0) + 1) }
        def dl = docLengths[docIdx]
        double score = 0.0
        queryTokens.each { rawQt ->
            def qt = _bm25Key(rawQt)
            def termFreq = tf.get(qt) ?: 0
            if (termFreq > 0) {
                def docFreq = df.get(qt) ?: 0
                def idf = Math.log((n - docFreq + 0.5) / (docFreq + 0.5) + 1.0)
                def num = termFreq * (k1 + 1)
                def den = termFreq + k1 * (1 - b + b * dl / avgDl)
                score += idf * num / den
            }
        }
        scores[docIdx] = score
    }
    return scores as List
}
def toolGetToolGuide(section, cursor = null, Map apiDocs = null) {
    if (apiDocs?.platform_api_search != null || apiDocs?.platform_api_page != null) {
        if (section) throw new IllegalArgumentException("section and platform_api_search / platform_api_page are separate lookups; send one.")
        if (apiDocs.platform_api_search != null && apiDocs.platform_api_page != null) {
            throw new IllegalArgumentException("Send platform_api_search or platform_api_page, not both: search first, then open a pageId it returns.")
        }
        return (apiDocs.platform_api_page != null) ? _platformApiPage(apiDocs.platform_api_page.toString(), cursor)
                                                    : _platformApiSearch(apiDocs.platform_api_search.toString(), cursor)
    }
    def sections = getToolGuideSections()
    def subSections = getToolGuideSubSections()
    if (section) {
        def key = section.toLowerCase().replaceAll(/[^a-z_]/, "_")
        if (sections.containsKey(key)) {
            def result = [success: true, section: key]
            if (subSections.containsKey(key)) result.subSections = subSections[key].keySet().toList()
            return _withGuidePage(result, _guideSectionServed(key, sections[key]), cursor)
        }
        def sub = guideSubSectionLookup(key)
        if (sub) {
            def result = [
                success: true,
                section: key,
                parentSection: sub.parent,
                subSections: subSections[sub.parent].keySet().toList(),
                note: "Part of the '${sub.parent}' section. A sibling sub-key may hold what you need; hub_get_tool_guide(section='${sub.parent}') returns all of it.".toString()
            ]
            return _withGuidePage(result, _guideSectionServed(key, sub.content), cursor)
        }
        return [
            success: false,
            error: "Unknown section: ${section}",
            availableSections: sections.keySet().toList(),
            availableSubSections: subSections.collectEntries { k, v -> [(k): v.keySet().toList()] }
        ]
    }
    def fullGuide = "Acknowledgment keys are published only when a single section is read.\n\n" +
        sections.collect { k, v -> v }.join("\n\n---\n\n")
    def result = [
        success: true,
        section: "full",
        availableSections: sections.keySet().toList(),
        availableSubSections: subSections.collectEntries { k, v -> [(k): v.keySet().toList()] }
    ]
    return _withGuidePage(result, fullGuide, cursor)
}
private Map _platformApiSearch(String query, cursor) {
    def terms = query.toLowerCase().split(/\s+/).findAll { it }
    if (!terms) throw new IllegalArgumentException("platform_api_search needs at least one word, e.g. 'eventsBetween' or 'hub variable'.")
    def index
    try {
        def raw = hubInternalGet("/developer-docs/index.json", null, 60)
        index = raw ? new groovy.json.JsonSlurper().parseText(raw) : null
    } catch (Exception e) {
        mcpLogError("discovery", "API documentation index read failed", e)
        def out = [success: false, error: "Could not read the hub's API documentation index: ${e.message}"]
        if (_hubFirmwareBefore("2.5.2")) out.note = "The on-hub API documentation needs firmware 2.5.2 or later."
        return out
    }
    if (!(index instanceof Map) || !(index.pages instanceof List)) {
        return [success: false, error: "The hub's API documentation index has an unexpected shape."]
    }
    def hits = []
    index.pages.each { pg ->
        if (!(pg instanceof Map)) return
        int sectionBoost = (pg.section == "protocols") ? 0 : 3
        String pageText = "${pg.id} ${pg.label} ${pg.className} ${pg.topic}".toLowerCase()
        if (terms.every { pageText.contains(it) }) {
            hits << [score: 3 + sectionBoost, pageId: pg.id, className: pg.className, label: pg.label, section: pg.section, kind: "page", usage: pg.usage]
        }
        def pgMethods = pg.get("methods")
        (pgMethods instanceof List ? pgMethods : []).each { m ->
            if (!(m instanceof Map)) return
            String name = (m.name ?: "").toString()
            String lname = name.toLowerCase()
            String text = "${name} ${m.signature} ${m.summary} ${pg.className} ${pg.label}".toLowerCase()
            if (!terms.every { text.contains(it) }) return
            int score = sectionBoost
            if (terms.any { it == lname }) score += 4
            else if (terms.every { lname.contains(it) }) score += 2
            hits << [score: score, pageId: pg.id, className: pg.className, label: pg.label, section: pg.section, kind: m.kind ?: "method",
                     name: name, signature: m.signature, summary: m.summary?.toString()?.take(400)]
        }
    }
    (index.guides instanceof List ? index.guides : []).each { g ->
        if (g instanceof Map && terms.every { "${g.title} ${g.summary}".toLowerCase().contains(it) }) {
            hits << [score: 1, kind: "guide", label: g.title, summary: g.summary, url: g.url]
        }
    }
    hits = hits.sort { -(it.score as int) }.collect { h -> h.findAll { k, v -> k != "score" && v != null } }
    def paged = _paginateList(hits, cursor != null ? cursor : "", 25, "hub_get_tool_guide")
    def out = [success: true, platformApiSearch: query, contentRevision: index.contentRevision, total: hits.size(), matches: paged.page]
    out.note = hits ? "Open a class with hub_get_tool_guide(platform_api_page=<pageId>) for full method descriptions. Methods the sandbox restricts to system apps are not marked; probe before relying on one." :
                      "No match. Search a method or class name, e.g. 'getHubFiles', 'DeviceWrapper', 'hub variable'."
    if (paged.nextCursor != null) out.nextCursor = paged.nextCursor
    return out
}
private Map _platformApiPage(String pageId, cursor) {
    if (!(pageId ==~ /[a-z0-9][a-z0-9-]*/)) throw new IllegalArgumentException("platform_api_page must be a pageId from platform_api_search, e.g. 'api-com-hubitat-app-devicewrapper'.")
    def pg
    try {
        def raw = hubInternalGet("/developer-docs/${pageId}.json", null, 30)
        pg = raw ? new groovy.json.JsonSlurper().parseText(raw) : null
    } catch (Exception e) {
        mcpLogError("discovery", "API documentation page read failed", e)
        return [success: false, error: "Could not read API documentation page '${pageId}': ${e.message}",
                note: "Check the pageId with hub_get_tool_guide(platform_api_search=...)." + (_hubFirmwareBefore("2.5.2") ? " The on-hub API documentation needs firmware 2.5.2 or later." : "")]
    }
    def pgMethods = (pg instanceof Map) ? pg.get("methods") : null
    if (!(pgMethods instanceof List)) return [success: false, error: "API documentation page '${pageId}' has an unexpected shape."]
    def methods = pgMethods.findAll { it instanceof Map }.collect { m ->
        def text = (m.descriptionMarkdown ?: m.summary)?.toString()?.trim()
        def entry = [kind: m.kind, name: m.name, signature: m.signature, description: text?.take(20000)]
        if (text && text.length() > 20000) entry.descriptionTruncated = true
        entry
    }
    def pageCursor = (cursor != null) ? cursor : ""
    def paged = _paginateList(methods, pageCursor, 40, "hub_get_tool_guide")
    while (paged.page.size() > 1 && groovy.json.JsonOutput.toJson(paged.page).length() > 60000) {
        paged = _paginateList(methods, pageCursor, paged.page.size() - 1, "hub_get_tool_guide")
    }
    def out = [success: true, pageId: pg.id, className: pg.className, label: pg.label, section: pg.section, topic: pg.topic, usage: pg.usage,
               extendsClass: pg.extendsClass, totalMethods: methods.size(), methods: paged.page]
    if (paged.nextCursor != null) out.nextCursor = paged.nextCursor
    return out
}
private Map _withGuidePage(Map result, content, cursor) {
    def paged = paginateGuideContent(content, cursor)
    result.content = paged.content
    if (paged.nextCursor != null || paged.offset > 0) {
        result.offset = paged.offset
        result.totalChars = paged.totalChars
    }
    if (paged.nextCursor != null) result.nextCursor = paged.nextCursor
    return result
}
def _getAllToolDefinitions_partDiscovery() {
    return [
        [
            name: "hub_get_tool_guide",
            description: "Get the deep-reference guide for an MCP tool topic[[FLAT_TRIM]] (exhaustive capability tables, wire formats, worked examples)[[/FLAT_TRIM]]. Read a write tool's section before calling that tool: the section publishes the acknowledgment key the best-practice gate requires, and best_practice_reference maps each write tool to its section. A `<parent>_<part>` key (e.g. set_rule_reference_conditions) returns just that part of its parent section; the bare parent key returns all of it.[[FLAT_TRIM]] A parent's response lists its own sub-keys.[[/FLAT_TRIM]] Prefer a section: omitting it returns the key list plus the first page of the whole guide (paged via nextCursor)[[FLAT_TRIM]], the largest response this tool produces, so on a timeout retry a specific section[[/FLAT_TRIM]].[[FLAT_TRIM]] platform_api_search / platform_api_page read the hub's own Groovy API documentation instead.[[/FLAT_TRIM]]",
            inputSchema: [
                type: "object",
                properties: [
                    section: [type: "string", description: "One section key from the enum. Omit to get the key list plus the first page of the full guide.", enum: ["device_authorization", "best_practice_reference", "tool_access", "hub_admin_write", "hub_admin_write_overview", "hub_admin_write_destructive", "hub_admin_write_radios", "hub_admin_write_devices", "hub_admin_write_code", "hub_admin_write_system", "virtual_devices", "update_device", "rules", "backup", "file_manager", "performance", "performance_overview", "performance_devices", "performance_diagnostics", "builtin_app_tools", "builtin_app_tools_overview", "builtin_app_tools_apps", "builtin_app_tools_rules", "builtin_app_tools_crud", "set_rule_reference", "set_rule_reference_overview", "set_rule_reference_triggers", "set_rule_reference_actions", "set_rule_reference_conditions", "set_rule_reference_walkstep", "set_rule_reference_responses", "set_rule_reference_guards", "set_rule_create_reference", "visual_rule_reference", "variables", "dashboards", "bundles", "rooms", "slow_ops"]],
                    cursor: [type: "string", description: "Continue a paged payload: pass the prior call's nextCursor. Omit otherwise -- a cursor is rejected on a payload that fit one response."],
                    platform_api_search: [type: "string", description: "[[FLAT_TRIM]]Instead of a section: search the hub's Groovy API docs, e.g. 'eventsBetween'.[[/FLAT_TRIM]]"],
                    platform_api_page: [type: "string", description: "[[FLAT_TRIM]]Instead of a section: one API docs class page by pageId.[[/FLAT_TRIM]]"]
                ]
            ]
        ],
        [
            name: "hub_search_tools",
            description: "Search all MCP tools by natural language query (BM25 ranking). Searches tool names, friendly titles, descriptions, and parameter names. Returns matching tools with their gateway location so you know how to call them. Use when unsure which gateway contains the tool you need.",
            inputSchema: [
                type: "object",
                properties: [
                    query: [type: "string", description: "Natural language search query (e.g. 'zigbee radio', 'delete app', 'memory leak', 'room management')"],
                    maxResults: [type: "integer", description: "Max results to return. Default: 5.", default: 5]
                ],
                required: ["query"]
            ]
        ],
    ]
}
