                break
            case "addAction":
                _rmValidateRoundZeroActionSpec(args.addAction as Map)
                break
        }
        return null
    } catch (IllegalArgumentException refusal) {
        return [
            success: false,
            appId: refusalAppId,
            error: refusal.message,
            wizardStuck: false,
            restoreHint: _rmPreflightRestoreHint()
