            appId: appId,
            backup: backup,
            triggers: triggerResults,
            actions: actionResults,
            health: health,
            updateRuleFailed: updateRuleFailed,
            subscriptionsNotLive: subscriptionsNotLive,
            updateRuleError: updateRuleError,
