        String detail = "${e.class.simpleName}: ${_bugReportScrubSecrets(_mcpClientString(e.message))}".toString()
        try {
            mcpLog("warn", "server", "MCP client identity read failed: ${detail}")
        } catch (Throwable ignored) {
        }
